<?php $rubricSection=$_GET['section']??'evaluation'; ?>
<div class="d-flex gap-2 mb-3 flex-wrap"><a class="filter-pill <?= $rubricSection==='evaluation'?'active':'' ?>" href="?view=rubrics&section=evaluation">Evaluation Rubrics</a><a class="filter-pill <?= $rubricSection==='detailed'?'active':'' ?>" href="?view=rubrics&section=detailed">Detailed Rubrics</a></div>
<?php if($rubricSection==='detailed'){include __DIR__.'/detailed-rubrics.php';return;} ?>
<?php
$myPts=$coordProgrammeTypes;$rubrics=$myPts?safeRun($pdo,"SELECT r.* FROM rubrics r WHERE r.is_locked=1 AND r.programme_type IN (".implode(',',array_fill(0,count($myPts),'?')).") AND r.id=(SELECT r2.id FROM rubrics r2 WHERE r2.programme_type=r.programme_type AND r2.evaluator_role=r.evaluator_role AND r2.is_locked=1 ORDER BY r2.version DESC,r2.id DESC LIMIT 1) ORDER BY FIELD(r.programme_type,'diploma_fyp1','diploma_fyp2','degree_fyp1','degree_fyp2'),FIELD(r.evaluator_role,'coordinator','supervisor','report_panel','presentation_panel')",$myPts)->fetchAll():[];
$selectedId=(int)($_GET['rubric_id']??($rubrics[0]['id']??0));$selected=null;foreach($rubrics as $r)if((int)$r['id']===$selectedId)$selected=$r;$criteria=$selected?safeRun($pdo,'SELECT * FROM rubric_criteria WHERE rubric_id=? ORDER BY sort_order,id',[$selectedId])->fetchAll():[];$total=(int)array_sum(array_column($criteria,'weight'));$expected=$selected?expectedRubricTotal($selected['programme_type'],$selected['evaluator_role']):0;$editing=($_GET['edit']??'')==='1';
?>
<?php if(($_GET['rubricmsg']??'')==='updated'): ?><div class="alert alert-success small">Evaluation rubric updated.</div><?php elseif(($_GET['rubricmsg']??'')==='total'): ?><div class="alert alert-danger small">The total marks must equal the required <?= (int)$expected ?> marks.</div><?php endif; ?>
<div class="row g-3"><div class="col-lg-4"><div class="card-fy"><div class="section-title">Evaluation Rubrics</div><?php foreach($rubrics as $r): ?><a href="?view=rubrics&section=evaluation&rubric_id=<?= (int)$r['id'] ?>" class="d-block text-decoration-none p-3 rounded-3 mb-2" style="border:1.5px solid <?= $selectedId===(int)$r['id']?'var(--theme)':'#eee' ?>"><strong class="small text-dark"><?= e(roleLabel($r['evaluator_role'])) ?></strong><div class="small text-muted"><?= e(programmeTypeLabel($r['programme_type'])) ?></div></a><?php endforeach; ?><?php if(!$rubrics): ?><p class="small text-muted">No evaluation rubrics are available.</p><?php endif; ?></div></div>
<div class="col-lg-8"><?php if($selected): ?><div class="card-fy"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><div class="section-title mb-1"><?= e(roleLabel($selected['evaluator_role'])) ?> Evaluation Rubric</div><div class="small text-muted"><?= e(programmeTypeLabel($selected['programme_type'])) ?></div></div><strong id="evaluationTotal" class="fs-5"><?= $total ?> / <?= $expected ?> marks</strong></div>
<?php if(!$editing): ?><div class="table-responsive mt-3"><table class="table-fy"><thead><tr><th>Criterion</th><th>Marks</th></tr></thead><tbody><?php foreach($criteria as $c): ?><tr><td><?= e($c['criteria_name']) ?></td><td><?= (int)$c['weight'] ?></td></tr><?php endforeach; ?></tbody></table></div><a href="?view=rubrics&section=evaluation&rubric_id=<?= $selectedId ?>&edit=1" class="btn-fy-orange mt-3"><i class="fa-solid fa-pen me-1"></i>Edit</a>
<?php else: ?><form method="post" id="evaluationRubricForm"><?= csrfField() ?><input type="hidden" name="action" value="update_evaluation_rubric"><input type="hidden" name="rubric_id" value="<?= $selectedId ?>"><div id="existingEvaluationCriteria" class="mt-3"><?php foreach($criteria as $c): ?><div class="row g-2 align-items-end mb-2 evaluation-criterion-row"><div class="col-md-9"><label class="form-label small fw-semibold">Criterion</label><input required maxlength="200" name="criteria_name[<?= (int)$c['id'] ?>]" value="<?= e($c['criteria_name']) ?>" class="form-control-fy w-100"></div><div class="col-md-3"><label class="form-label small fw-semibold">Marks</label><input required type="number" min="1" max="<?= $expected ?>" name="weight[<?= (int)$c['id'] ?>]" value="<?= (int)$c['weight'] ?>" class="form-control-fy w-100 evaluation-weight"></div></div><?php endforeach; ?></div><div id="newEvaluationCriteria"></div><button type="button" class="btn-fy-outline mt-2" id="addEvaluationCriterion"><i class="fa-solid fa-plus me-1"></i>Add Criterion</button><div class="d-flex gap-2 mt-3"><button class="btn-fy-orange">Update</button><a class="btn-fy-outline" href="?view=rubrics&section=evaluation&rubric_id=<?= $selectedId ?>">Cancel</a></div></form><?php endif; ?></div><?php else: ?><div class="card-fy text-center text-muted py-5">No rubric selected.</div><?php endif; ?></div></div>
<script>(function(){const box=document.getElementById('newEvaluationCriteria'),btn=document.getElementById('addEvaluationCriterion'),total=document.getElementById('evaluationTotal');let n=0;function recalc(){let sum=0;document.querySelectorAll('.evaluation-weight').forEach(x=>sum+=Number(x.value||0));if(total)total.textContent=sum+' / <?= (int)$expected ?> marks';}btn?.addEventListener('click',()=>{const row=document.createElement('div');row.className='row g-2 align-items-end mb-2 evaluation-criterion-row';row.innerHTML='<div class="col-md-9"><label class="form-label small fw-semibold">New criterion</label><input required maxlength="200" name="new_criteria_name[]" class="form-control-fy w-100"></div><div class="col-md-3"><label class="form-label small fw-semibold">Marks</label><input required type="number" min="1" max="<?= (int)$expected ?>" name="new_weight[]" value="1" class="form-control-fy w-100 evaluation-weight"></div>';box.appendChild(row);row.querySelector('.evaluation-weight').addEventListener('input',recalc);recalc();n++;});document.querySelectorAll('.evaluation-weight').forEach(x=>x.addEventListener('input',recalc));})();</script>
